	    LOGGER.info("handling RemoveOwnersFromPolicyEvent " );
	
	    Policy parentEntity = repository.findById(parentId).get();
	    Person child = registry.project( Person.class, removeFrom.getPersonId());
	    
	    parentEntity.getOwners().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
